package com.way2jobs.scraper;
import com.way2jobs.entity.*; import com.way2jobs.scraper.config.ScraperProperties; import com.way2jobs.scraper.dto.ScraperRunResult; import com.way2jobs.scraper.model.ScrapedJob; import com.way2jobs.scraper.source.JobSource; import com.way2jobs.service.FirebaseMessagingService; import lombok.*; import lombok.extern.slf4j.Slf4j; import org.springframework.beans.factory.ObjectProvider; import org.springframework.stereotype.Service; import java.time.Instant; import java.util.*; import java.util.concurrent.atomic.AtomicBoolean;
@Service @RequiredArgsConstructor @Slf4j public class JobScraperService {private final ScraperProperties props;private final ScraperLookupService lookups;private final ScraperValidationService validation;private final ScraperPersistenceService persistence;private final List<JobSource> sources;private final ObjectProvider<FirebaseMessagingService> fcm;private final AtomicBoolean running=new AtomicBoolean(false);private volatile ScraperRunResult lastResult;public boolean isRunning(){return running.get();}public ScraperRunResult getLastResult(){return lastResult;}public ScraperRunResult run(){ScraperRunResult r=start();if(!props.isEnabled()){r.addMessage("scraper disabled");return finish(r);}if(!running.compareAndSet(false,true)){r.addMessage("scraper already running");return finish(r);}try{lookups.refreshCaches();Category cat=lookups.resolveCategory(props.getDefaultCategoryName()).orElse(null);if(cat==null){r.addMessage("Category '"+props.getDefaultCategoryName()+"' does not exist. Create it first via POST /api/categories.");return finish(r);}for(var entry:props.getSources().entrySet()){State state=lookups.resolveState(entry.getKey()).orElse(null);if(state==null){r.addMessage("state not found: "+entry.getKey());continue;}JobSource source=sources.stream().findFirst().orElse(null);if(source==null){r.addMessage("no job source configured");break;}try{r.setPagesVisited(r.getPagesVisited()+1);List<ScrapedJob> rows=source.fetch(entry.getKey(),entry.getValue(),props);r.setRowsFound(r.getRowsFound()+rows.size());if(rows.isEmpty())log.warn("No rows found for source {}",entry.getValue());for(ScrapedJob row:rows){if(r.getImported()>=props.getMaxJobsPerRun())break;ScraperValidationService.ValidationResult v=validation.validate(row);if(v.reason()!=null){r.setSkipped(r.getSkipped()+1);r.addMessage(v.reason());continue;}Department d=lookups.resolveDepartment(v.job().getOrganizationName()).orElse(null);if(d==null){r.setSkipped(r.getSkipped()+1);r.addMessage("department not found: "+v.job().getOrganizationName());continue;}ScraperPersistenceService.PersistOutcome o=persistence.persistOne(v.job(),d,cat,state);if(o instanceof ScraperPersistenceService.Imported)r.setImported(r.getImported()+1);else if(o instanceof ScraperPersistenceService.Duplicate)r.setDuplicates(r.getDuplicates()+1);else {r.setFailed(r.getFailed()+1);r.addMessage(((ScraperPersistenceService.Failed)o).reason());}}if(props.getPoliteDelayMs()>0)Thread.sleep(props.getPoliteDelayMs());}catch(Exception e){r.setFailed(r.getFailed()+1);r.addMessage("source failed: "+e.getMessage());}}if(props.isNotifyOnNewJobs()&&r.getImported()>0)try{int count=r.getImported();fcm.ifAvailable(f->f.sendNotification("New Government Jobs",count+" new jobs added. Tap to view.",null,Map.of("type","SCRAPER_SUMMARY","count",String.valueOf(count))));}catch(Exception e){log.warn("summary push failed",e);}return finish(r);}finally{running.set(false);}}private ScraperRunResult start(){ScraperRunResult r=new ScraperRunResult();r.setStartedAt(Instant.now());return r;}private ScraperRunResult finish(ScraperRunResult r){r.setFinishedAt(Instant.now());r.setDurationMs(r.getFinishedAt().toEpochMilli()-r.getStartedAt().toEpochMilli());lastResult=r;return r;}}
